package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen3Test {









    @Test
    public void testCreateNumber_IntegerTypes() {
        // Test Integer path
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        // Test Long path
        assertEquals(Long.valueOf(123456789L), NumberUtils.createNumber("123456789"));
        // Test BigInteger path (too big for long)
        String bigIntStr = "9223372036854775808"; // Long.MAX_VALUE + 1
        assertTrue(NumberUtils.createNumber(bigIntStr) instanceof BigInteger);
    }












}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen3Test {











    @Test
    public void testCreateNumber_DecimalAndExponent() {
        // Test Float path
        assertEquals(Float.valueOf(1.23f), NumberUtils.createNumber("1.23f"));
        // Test Double path
        assertEquals(Double.valueOf(1.23d), NumberUtils.createNumber("1.23d"));
        // Test BigDecimal path (when float/double fails precision/infinity)
        // Using a very large number that would be infinite in Float
        assertEquals(new BigDecimal("1e100"), NumberUtils.createNumber("1e100"));
        // Test scientific notation without suffix
        assertEquals(Double.valueOf(1.23e2), NumberUtils.createNumber("1.23e2"));
    }










}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen3Test {













    @Test
    public void testCreateNumber_Suffixes() {
        // Long suffixes
        assertEquals(Long.valueOf(100L), NumberUtils.createNumber("100L"));
        assertEquals(Long.valueOf(-100L), NumberUtils.createNumber("-100l"));
        // BigInteger suffix
        String hugeLong = "9223372036854775808";
        assertTrue(NumberUtils.createNumber(hugeLong + "L") instanceof BigInteger);

        // Float suffixes
        assertEquals(Float.valueOf(1.2f), NumberUtils.createNumber("1.2F"));
        // Double suffixes
        assertEquals(Double.valueOf(1.2d), NumberUtils.createNumber("1.2D"));
    }








}

package org.apache.commons.lang.math;

