public class NumberUtils_createNumber_TriageGen3Test {















    @Test
    public void testCreateNumber_InvalidSuffixes() {
        // Invalid suffix for Long (contains decimal)
        try {
            NumberUtils.createNumber("1.2L");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {}

        // Invalid suffix (not a digit and not a valid suffix)
        try {
            NumberUtils.createNumber("1.2z");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {}
    }






}

